<script setup lang="ts">
import type { ProductInput } from '~/services/moderator.api'
import { moderatorApi } from '~/services/moderator.api'
import { catalogApi } from '~/services/catalog.api'
import type { Category, Color, Product, Size, Technique } from '~/types/catalog'
definePageMeta({ layout: 'moderator', middleware: 'moderator' })
const route = useRoute(); const { data: products, error: loadError, refresh } = await useAsyncData<Product[]>('moderator-edit-products', async () => (await moderatorApi.products()).productsAdmin)
const { data: metadata } = await useAsyncData<{ getCategories: Category[]; getTechniques: Technique[]; getSizes: Size[]; getColors: Color[] }>('edit-metadata', () => catalogApi.metadata())
const product = computed(() => products.value?.find((item) => item.id === route.params.id)); const error = ref(''); const success = ref(''); const saving = ref(false); const imageUrl = ref(''); const imageAlt = ref('')
const form = reactive<ProductInput>({ name: '', slug: '', description: '', story: '', price: 0, discountPercentage: 0, categoryId: '', techniqueId: '', returnable: true })
watch(product, (item) => { if (item) Object.assign(form, { name: item.name, slug: item.slug, description: item.description, story: item.story, price: item.price, discountPercentage: item.discountPercentage, categoryId: item.category.id, techniqueId: item.technique.id, returnable: item.returnable }) }, { immediate: true })
async function save() { if (!product.value) return; error.value = ''; success.value = ''; saving.value = true; try { await moderatorApi.update(product.value.id, { ...form }); success.value = 'Product details saved.'; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to save product.' } finally { saving.value = false } }
async function saveStock(variantId: string, event: Event) { error.value = ''; try { await moderatorApi.stock(variantId, Number((event.target as HTMLInputElement).value)); await refresh(); success.value = 'Stock updated.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to update stock.' } }
async function addImage() { if (!product.value || !imageUrl.value || !imageAlt.value) return; const url = imageUrl.value; const alt = imageAlt.value; error.value = ''; try { await moderatorApi.addImage(product.value.id, url, alt, product.value.images.length); imageUrl.value = ''; imageAlt.value = ''; await refresh(); success.value = 'Image added.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to add image.' } }
async function removeImage(id: string) { if (!product.value) return; try { await moderatorApi.removeImage(id); await refresh(); success.value = 'Image removed.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to remove image.' } }
async function moveImage(index: number, offset: number) { if (!product.value) return; const ids = product.value.images.map((image) => image.id); const target = index + offset; const currentId = ids[index]; const targetId = ids[target]; if (!currentId || !targetId) return; ids[index] = targetId; ids[target] = currentId; try { await moderatorApi.reorderImages(product.value.id, ids); await refresh(); success.value = 'Image order updated.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to reorder images.' } }
</script>
<template><div><NuxtLink to="/moderator/products" class="text-sm font-bold underline">← Back to products</NuxtLink><div v-if="loadError || !product" class="mt-6 rounded-lg bg-rose-50 p-5 text-rose-800">Product not found or unavailable.</div><form v-else class="mt-5 space-y-7" @submit.prevent="save"><div><p class="text-xs font-bold uppercase tracking-widest text-slate-500">Product editor</p><h1 class="mt-2 font-display text-4xl">{{ product.name }}</h1></div><p v-if="error" class="rounded-lg bg-rose-50 p-4 text-rose-800">{{ error }}</p><p v-if="success" class="rounded-lg bg-emerald-50 p-4 text-emerald-800">{{ success }}</p><section class="card p-6"><h2 class="font-display text-2xl">Details and pricing</h2><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="label">Name<input v-model="form.name" class="field mt-1" required></label><label class="label">Slug<input v-model="form.slug" class="field mt-1" required></label><label class="label">Category<select v-model="form.categoryId" class="field mt-1"><option v-for="item in metadata?.getCategories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="label">Technique<select v-model="form.techniqueId" class="field mt-1"><option v-for="item in metadata?.getTechniques" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="label">Price (USD)<input v-model.number="form.price" class="field mt-1" type="number" min="0" step="0.01" required></label><label class="label">Discount (%)<input v-model.number="form.discountPercentage" class="field mt-1" type="number" min="0" max="100" required></label></div><label class="label mt-4">Description<textarea v-model="form.description" class="field mt-1 min-h-28" required/></label><label class="label mt-4">Story<textarea v-model="form.story" class="field mt-1 min-h-32" required/></label><label class="mt-4 flex items-center gap-2 text-sm font-semibold"><input v-model="form.returnable" type="checkbox"> Returnable product</label><button class="button-primary mt-6" :disabled="saving">{{ saving ? 'Saving…' : 'Save details' }}</button></section><section class="card p-6"><h2 class="font-display text-2xl">Variants and stock</h2><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[550px] text-left text-sm"><thead><tr class="border-b"><th class="p-3">Color</th><th class="p-3">Size</th><th class="p-3">SKU</th><th class="p-3">Stock</th></tr></thead><tbody><tr v-for="variant in product.variants" :key="variant.id" class="border-b"><td class="p-3">{{ variant.color.name }}</td><td class="p-3">{{ variant.size.name }}</td><td class="p-3 font-mono text-xs">{{ variant.sku }}</td><td class="p-3"><input class="field w-28" type="number" min="0" :value="variant.stock" @change="saveStock(variant.id, $event)"></td></tr></tbody></table></div></section><section class="card p-6"><h2 class="font-display text-2xl">Images</h2><div class="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"><div v-for="image in product.images" :key="image.id" class="aspect-square overflow-hidden rounded-lg bg-slate-100"><img :src="image.url" :alt="image.alt" class="h-full w-full object-cover"></div></div><div class="mt-5 grid gap-3 md:grid-cols-[1fr_1fr_auto]"><input v-model="imageUrl" class="field" type="url" placeholder="https://… image URL"><input v-model="imageAlt" class="field" placeholder="Accessible image description"><button type="button" class="button-outline" @click="addImage">Add image</button></div></section></form></div></template>
